export const language = () => document.documentElement.lang === 'da' ? 'da' : 'en';
export const locale = () => language() === 'da' ? 'da-DK' : 'en-GB';
export const t = value => language() === 'da' ? (da[value] ?? value) : value;
const originals = new WeakMap();
// Only static shell copy is registered. Conversations, saved data and generated content are never rewritten.
export function registerShell(root = document.body) {
 const walk = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
 const nodes=[]; while(walk.nextNode()) nodes.push(walk.currentNode);
 for(const node of nodes) { const key=node.textContent.trim(); if(Object.hasOwn(da,key)) originals.set(node,{text:node.textContent,key}); }
 for(const el of root.querySelectorAll('[aria-label],[title],[placeholder],[data-prompt],[data-short]')) {
  const attrs={}; for(const name of ['aria-label','title','placeholder','data-prompt','data-short']) {const value=el.getAttribute(name);if(Object.hasOwn(da,value))attrs[name]=value;} if(Object.keys(attrs).length)originals.set(el,attrs);
 }
}
export function translateShell(root = document.body) {
 const walk=document.createTreeWalker(root,NodeFilter.SHOW_ALL); const nodes=[root];while(walk.nextNode())nodes.push(walk.currentNode);
 for(const node of nodes){const source=originals.get(node);if(!source)continue;if(node.nodeType===3)node.textContent=source.text.replace(source.key,t(source.key));else for(const [name,value] of Object.entries(source))node.setAttribute(name,t(value));}
 document.title='Banking · '+t('AI Bank Advisor');
}
